# Build HTML
def esc(text):
    """Escape HTML entities."""
    return text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')

def md_to_html(text):
    """Simple markdown to HTML conversion."""
    result = []
    in_list = False

    for line in text.split('\n'):
        stripped = line.strip()

        # Empty line
        if not stripped:
            if in_list:
                result.append('</ul>')
                in_list = False
            result.append('')
            continue

        # Headers
        if stripped.startswith('### '):
            if in_list:
                result.append('</ul>')
                in_list = False
            result.append(f'<h3>{esc(stripped[4:])}</h3>')
            continue
        if stripped.startswith('#### '):
            if in_list:
                result.append('</ul>')
                in_list = False
            result.append(f'<h4>{esc(stripped[5:])}</h4>')
            continue

        # Bold/italic markers
        # **text** → <strong>text</strong>
        # *text* → <em>text</em>
        def format_inline(t):
            t = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', t)
            t = re.sub(r'\*(.+?)\*', r'<em>\1</em>', t)
            return t

        # List items
        if stripped.startswith('- '):
            if not in_list:
                result.append('<ul>')
                in_list = True
            result.append(f'<li>{format_inline(esc(stripped[2:]))}</li>')
            continue

        if stripped.startswith('* '):
            if not in_list:
                result.append('<ul>')
                in_list = True
            result.append(f'<li>{format_inline(esc(stripped[2:]))}</li>')
            continue

        # Numbered list items
        if re.match(r'^\d+\.\s', stripped):
            if not in_list:
                result.append('<ol>')
                in_list = True
            content = re.sub(r'^\d+\.\s', '', stripped)
            result.append(f'<li>{format_inline(esc(content))}</li>')
            continue

        # Close list if we were in one
        if in_list:
            result.append('</ul>' if not stripped[0].isdigit() else '</ol>')
            in_list = False

        # Normal paragraph — handle em dashes and quotes
        para = format_inline(esc(stripped))
        # Em dash fix: space-dash-space or double dash
        para = para.replace(' . ', ' — ')
        para = para.replace(' .', '—')
        result.append(f'<p>{para}</p>')

    if in_list:
        result.append('</ul>')

    return '\n'.join(result)

